render=function(){if(!authReady)return;document.body.classList.toggle('auth-screen',!account&&!guest);if(!account&&!guest){document.body.classList.remove('focus-mode','onboarding');document.getElementById('nav').innerHTML='';document.getElementById('topbar').innerHTML='';document.getElementById('app').innerHTML=authView();return}renderCourse();const A=document.getElementById('app'),B=document.getElementById('topbar'),focus=A.dataset.page==='lic';if(!focus){B.insertAdjacentHTML('beforeend',`<div class="header-controls"><select class="mobile-course" aria-label="Idioma de estudo" onchange="changeCourse(this.value)"><option value="it" ${course==='it'?'selected':''}>Italiano</option><option value="en" ${course==='en'?'selected':''}>Inglês</option></select><button id="sync-control" class="sync-control" data-state="${syncState}" onclick="syncAction()">${syncLabel()}</button></div>`)}A.insertAdjacentHTML('afterbegin','<div id="conflict-slot">'+conflictView()+'</div>');if(A.dataset.page==='perfil'&&S.p.on){A.insertAdjacentHTML('beforeend',accountPanel());const note=A.querySelector('.data-card .mu');if(note)note.textContent=account?'Seu progresso é salvo nesta conta. Exporte um backup ou importe dados para o idioma atual.':'Seus dados ficam neste navegador. Entre para salvar na conta.'}if(!S.p.on){A.insertAdjacentHTML('afterbegin',`<label for="onboard-language">O que você quer aprender?</label><select id="onboard-language" onchange="changeCourse(this.value)"><option value="it" ${course==='it'?'selected':''}>Italiano</option><option value="en" ${course==='en'?'selected':''}>Inglês</option></select>`);const intro=A.querySelector('div[style] .mu');if(intro)intro.textContent=language().name+' para quem fala português. Um passo de cada vez.'}}
async function boot(){
 try{const d=await api('/api/auth/me');account=d.user;authReady=true;if(account){await openCourse(account.preferred_language||'it');if(records[stateKey(owner(),course)]?.dirty&&!conflict)syncProgress()}}catch(e){authReady=true;authError=location.protocol==='file:'?'Abra o PARLO pelo servidor (npm start) para entrar na sua conta.':'Não foi possível conectar ao servidor. Confira sua conexão e tente novamente.'}render();
}
addEventListener('hashchange',()=>{st=S.sess?.feedback||{};render();scrollTo(0,0)});
addEventListener('online',()=>{render();syncProgress()});addEventListener('offline',()=>{syncState=account?'offline':'local';render()});

setInterval(()=>{if(account&&!document.hidden&&!syncBusy&&!conflict&&records[stateKey(owner(),course)]?.dirty)syncProgress()},15000);
boot();
